-- G-132 M2 (D400): thread systems as data, and the site's three first ones as rows.

-- CreateTable
CREATE TABLE "ThreadSystem" (
    "id" TEXT NOT NULL,
    "key" TEXT NOT NULL,
    "label" TEXT NOT NULL,
    "note" TEXT,
    "source" TEXT,
    "licence" TEXT,
    "threads" TEXT NOT NULL,
    "threadCount" INTEGER NOT NULL,
    "position" INTEGER NOT NULL DEFAULT 0,
    "ownerId" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "ThreadSystem_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "ThreadSystem_ownerId_key_key" ON "ThreadSystem"("ownerId", "key");

-- A site system's key is unique too: the index above lets any number of null owners share one.
CREATE UNIQUE INDEX "ThreadSystem_site_key_key" ON "ThreadSystem"("key") WHERE "ownerId" IS NULL;

-- AddForeignKey
ALTER TABLE "ThreadSystem" ADD CONSTRAINT "ThreadSystem_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- The site's systems as they were compiled in before (tests/fixtures/thread-systems/ holds the same lists).
